<div class="play">
  <div class="play__top">
    <span class="logo play__logo"><span class="logo__mark">?</span>Quizzy</span>
    <span><%= @player ? "Hi, #{@player.name}!" : @quiz.title %></span>
  </div>

  <% if @game.finished? %>
    <div class="play__body">
      <div class="waiting">
        <div class="waiting__gem">?</div>
        <h1 class="play-title">The quiz is over</h1>
      </div>
    </div>
  <% elsif @player.nil? %>
    <div class="play__body">
      <h1 class="play-title"><%= @quiz.title %></h1>
      <% if @error.present? %>
        <div class="errors"><%= @error %></div>
      <% end %>
      <%= form_with url: join_play_game_path(@game.code), method: :post, local: true, class: "join-form", data: { join_form: true } do %>
        <div class="field">
          <label for="player_name" class="field-label">Your name</label>
          <input type="text" id="player_name" name="name" class="input" placeholder="Your name" aria-label="Your name" required autofocus autocomplete="off">
        </div>
        <button type="submit" class="btn btn--pink">Join</button>
      <% end %>
    </div>
  <% elsif @game.waiting? %>
    <div class="play__body">
      <div class="waiting">
        <div class="waiting__gem">?</div>
        <h1 class="play-title">Hi, <%= @player.name %>!</h1>
        <p class="play-lead">Waiting for the quiz to start…</p>
      </div>
    </div>
  <% elsif @game.question_open? %>
    <div class="play__body play__body--top">
      <div class="play-question__num">Question <%= @question_number %> of <%= @total_questions %></div>
      <div class="play-question__body"><%= @current_question.body %></div>
      <div class="play-options">
        <% @options.each_with_index do |option, idx| %>
          <% picked = (@picked_option_id == option.id) %>
          <%= form_with url: answer_play_game_path(@game.code), method: :post, local: true, data: { answer_form: true, option_id: option.id } do %>
            <input type="hidden" name="option_id" value="<%= option.id %>">
            <button type="submit"
                    class="play-option <%= 'is-picked' if picked %>"
                    data-option-button="<%= option.id %>"
                    title="<%= option.text %>"
                    aria-label="<%= option.text %>">
              <span class="play-option__letter" data-letter="<%= ("A".ord + idx).chr %>"></span>
              <span class="play-option__title"><%= option.text %></span>
              <% if picked %>
                <span class="play-option__mark">Your answer</span>
              <% end %>
            </button>
          <% end %>
        <% end %>
      </div>
    </div>
  <% elsif @game.question_closed? %>
    <div class="play__body play__body--top">
      <div class="play-question__num">Question <%= @question_number %> of <%= @total_questions %></div>
      <div class="play-question__body"><%= @current_question.body %></div>
      <div class="play-options is-locked is-revealed">
        <% @options.each_with_index do |option, idx| %>
          <% picked = (@picked_option_id == option.id) %>
          <button type="button"
                  class="play-option <%= 'is-picked' if picked %> <%= 'is-correct' if option.correct? %>"
                  disabled
                  title="<%= option.text %>"
                  aria-label="<%= option.text %>">
            <span class="play-option__letter" data-letter="<%= ("A".ord + idx).chr %>"></span>
            <span class="play-option__title"><%= option.text %></span>
            <% if picked %>
              <span class="play-option__mark">Your answer</span>
            <% end %>
          </button>
        <% end %>
      </div>

      <% if @picked_option.nil? %>
        <div class="play-status play-status--neutral">No answer</div>
      <% elsif @picked_option.correct? %>
        <div class="play-status play-status--right">Correct!</div>
      <% else %>
        <div class="play-status play-status--wrong">Wrong!</div>
      <% end %>
    </div>
  <% end %>
</div>
